import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { nextCookies } from "better-auth/next-js";
import { BASE_URL } from "@/config/base-url";
import { env } from "@/env";
import { resend } from "@/lib/resend";
import { db } from "@/server/db";
import { accounts, sessions, users, verificationTokens } from "@/server/db/schema";

/**
 * Better Auth mounts at this path. Auth.js owns `/api/auth`, so the two
 * handlers never collide and both can exist in the same deployment.
 */
export const BETTER_AUTH_BASE_PATH = "/api/better-auth";

/**
 * Better Auth reads and writes the app's own auth tables (`users`, `accounts`,
 * `sessions`, `verificationTokens`), the same ones Auth.js and every service
 * in the app use. Field names that differ are mapped below; columns Auth.js
 * never had were added to the schema as nullable extras.
 *
 * @see https://www.better-auth.com/docs/concepts/database
 */
const betterAuthTables = {
  user: users,
  session: sessions,
  account: accounts,
  verification: verificationTokens,
};

const FROM_EMAIL = env.RESEND_FROM_EMAIL ?? "noreply@example.com";

/**
 * Email delivery goes through the existing Resend client. Without a
 * `RESEND_API_KEY` there is nothing to send with, so verification is not
 * required and reset emails are logged instead of sent.
 */
const canSendEmail = Boolean(resend);

async function sendEmail(to: string, subject: string, html: string) {
  if (!resend) {
    console.warn(`Better Auth: RESEND_API_KEY is not set, skipping email "${subject}" to ${to}`);
    return;
  }
  await resend.emails.send({ from: FROM_EMAIL, to, subject, html });
}

/**
 * Main Better Auth configuration
 * @see https://www.better-auth.com/docs/configuration
 *
 * Built only when Better Auth is enabled (`NEXT_PUBLIC_FEATURE_BETTER_AUTH_ENABLED`),
 * which requires `DATABASE_URL` plus `BETTER_AUTH_SECRET` or `APP_SECRET`.
 */
export const auth = (() => {
  // Better Auth requires a database connection
  if (!db) {
    throw new Error(
      "Better Auth requires a database connection. Please set the DATABASE_URL environment variable."
    );
  }

  return betterAuth({
    basePath: BETTER_AUTH_BASE_PATH,

    database: drizzleAdapter(db, {
      provider: "pg",
      schema: betterAuthTables,
    }),

    emailAndPassword: {
      enabled: true,
      requireEmailVerification: canSendEmail,
      sendResetPassword: async ({ user, url }) => {
        await sendEmail(
          user.email,
          "Reset your password",
          `<p>Someone asked to reset the password for this account.</p><p><a href="${url}">Choose a new password</a></p><p>If that was not you, ignore this email.</p>`
        );
      },
    },

    emailVerification: {
      sendVerificationEmail: async ({ user, url }) => {
        await sendEmail(
          user.email,
          "Verify your email",
          `<p>Welcome! Confirm your email address to finish signing up.</p><p><a href="${url}">Verify email</a></p>`
        );
      },
    },

    session: {
      expiresIn: 60 * 60 * 24 * 7, // 7 days
      updateAge: 60 * 60 * 24, // 1 day
      fields: {
        token: "sessionToken",
        expiresAt: "expires",
      },
    },

    user: {
      fields: {
        // Auth.js stores a timestamp in `emailVerified`; Better Auth wants a boolean.
        emailVerified: "emailVerifiedFlag",
      },
      additionalFields: {
        // The app's role column. `input: false` keeps sign-up bodies from setting it.
        role: {
          type: "string",
          required: false,
          defaultValue: "user",
          input: false,
        },
        // Read-only view of the Auth.js verification timestamp so the session
        // facade can hand the app the `Date | null` it already expects.
        emailVerifiedAt: {
          type: "date",
          required: false,
          input: false,
          fieldName: "emailVerified",
        },
      },
    },

    account: {
      fields: {
        accountId: "providerAccountId",
        providerId: "provider",
        accessToken: "access_token",
        refreshToken: "refresh_token",
        idToken: "id_token",
      },
      additionalFields: {
        // Auth.js requires `type` on every account row; filled in by the hook below.
        type: {
          type: "string",
          required: false,
          input: false,
        },
      },
    },

    verification: {
      fields: {
        value: "token",
        expiresAt: "expires",
      },
    },

    databaseHooks: {
      user: {
        create: {
          before: (user) =>
            Promise.resolve({
              data: {
                ...user,
                // Auth.js defaults the timestamp to now; only stamp it when verified.
                emailVerifiedAt: user.emailVerified ? new Date() : null,
              },
            }),
        },
        update: {
          before: (user) => {
            if (!("emailVerified" in user)) return Promise.resolve();
            return Promise.resolve({
              data: { ...user, emailVerifiedAt: user.emailVerified ? new Date() : null },
            });
          },
        },
      },
      account: {
        create: {
          before: (account) =>
            Promise.resolve({
              data: {
                ...account,
                type: account.providerId === "credential" ? "credentials" : "oauth",
              },
            }),
        },
      },
    },

    // Social providers configuration - uses standard OAuth env vars
    socialProviders: {
      // Google OAuth
      ...(env.AUTH_GOOGLE_ID &&
        env.AUTH_GOOGLE_SECRET && {
          google: {
            clientId: env.AUTH_GOOGLE_ID,
            clientSecret: env.AUTH_GOOGLE_SECRET,
          },
        }),

      // GitHub OAuth
      ...(env.AUTH_GITHUB_ID &&
        env.AUTH_GITHUB_SECRET && {
          github: {
            clientId: env.AUTH_GITHUB_ID,
            clientSecret: env.AUTH_GITHUB_SECRET,
          },
        }),

      // Discord OAuth
      ...(env.AUTH_DISCORD_ID &&
        env.AUTH_DISCORD_SECRET && {
          discord: {
            clientId: env.AUTH_DISCORD_ID,
            clientSecret: env.AUTH_DISCORD_SECRET,
          },
        }),
    },

    secret: env?.BETTER_AUTH_SECRET ?? env?.AUTH_SECRET,
    baseURL: env?.BETTER_AUTH_BASE_URL ?? BASE_URL,

    trustedOrigins: [env?.BETTER_AUTH_BASE_URL ?? BASE_URL],

    // Sets the session cookie from server actions and route handlers.
    // Must stay the last plugin.
    plugins: [nextCookies()],
  });
})();

export type Auth = typeof auth;

import { APIError } from "better-auth/api";
import type { Auth } from "@/server/better-auth/config";
import type { Session } from "next-auth";
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { BASE_URL } from "@/config/base-url";
import { routes } from "@/config/routes";
import { STATUS_CODES } from "@/config/status-codes";
import { type BetterAuthSessionResult, mapBetterAuthSession } from "@/lib/auth/session-mapping";
import { logger } from "@/lib/logger";

export { type BetterAuthSessionResult, mapBetterAuthSession };

/**
 * Better Auth behind the `@/server/auth` facade.
 *
 * Everything in the app reads sessions through `auth()` from `@/server/auth`
 * and expects the Auth.js shape (`{ user, expires }` with the augmented
 * `User`). This module produces that shape from Better Auth so the rest of the
 * app does not know which strategy is active.
 *
 * `@/server/better-auth/config` builds the Better Auth instance at import time
 * and throws without a database, so it is imported lazily here: this file is
 * always loaded by the facade, but the instance only when the strategy is on.
 */

async function getBetterAuth(): Promise<Auth> {
  const { auth } = await import("@/server/better-auth/config");
  return auth;
}

/**
 * Current session from the request cookies, in the app's shape. `null` when
 * signed out or when Better Auth cannot be reached; the caller decides whether
 * that means a redirect.
 */
export async function getBetterAuthSession(): Promise<Session | null> {
  try {
    const auth = await getBetterAuth();
    const result = await auth.api.getSession({ headers: await headers() });
    return mapBetterAuthSession(result);
  } catch (error) {
    logger.error("Better Auth: failed to read session", error);
    return null;
  }
}

interface SignInOptions {
  redirectTo?: string;
  callbackUrl?: string;
  redirect?: boolean;
  email?: string;
  password?: string;
  [key: string]: unknown;
}

const toOptions = (options?: FormData | SignInOptions): SignInOptions =>
  options instanceof FormData ? Object.fromEntries(options) : (options ?? {});

const absoluteUrl = (path: string) => new URL(path, BASE_URL).toString();

/** Better Auth reports a bad email or password as a 401 `APIError`. */
const isCredentialsError = (error: unknown) =>
  error instanceof APIError && (error.statusCode === 401 || error.statusCode === 403);

/**
 * `signIn(provider, options)` with Auth.js semantics: a social provider starts
 * the OAuth flow and redirects to it, `"credentials"` signs in with email and
 * password. `redirect: false` returns `{ ok, url }` instead of redirecting.
 */
export async function betterAuthSignIn(provider?: string, options?: FormData | SignInOptions) {
  const opts = toOptions(options);
  const redirectTo = opts.redirectTo ?? opts.callbackUrl ?? routes.home;
  const shouldRedirect = opts.redirect !== false;
  const auth = await getBetterAuth();
  const requestHeaders = await headers();

  if (!provider || provider === "credentials") {
    const email = typeof opts.email === "string" ? opts.email : "";
    const password = typeof opts.password === "string" ? opts.password : "";
    try {
      await auth.api.signInEmail({
        body: { email, password, callbackURL: absoluteUrl(redirectTo) },
        headers: requestHeaders,
      });
    } catch (error) {
      if (isCredentialsError(error)) {
        if (!shouldRedirect) return { ok: false, error: STATUS_CODES.CREDENTIALS.message };
        throw new Error(STATUS_CODES.CREDENTIALS.message);
      }
      throw error;
    }
    if (shouldRedirect) redirect(redirectTo);
    return { ok: true, url: redirectTo };
  }

  const result = await auth.api.signInSocial({
    body: { provider, callbackURL: absoluteUrl(redirectTo), disableRedirect: true },
    headers: requestHeaders,
  });
  const url = result?.url;
  if (!url) {
    throw new Error(`Better Auth: provider "${provider}" returned no authorization URL`);
  }
  if (shouldRedirect) redirect(url);
  return { ok: true, url };
}

/**
 * `signOut(options)` with Auth.js semantics: clears the session cookie, then
 * redirects unless `redirect: false`.
 */
export async function betterAuthSignOut(options?: SignInOptions) {
  const opts = toOptions(options);
  const redirectTo = opts.redirectTo ?? routes.home;
  const auth = await getBetterAuth();
  try {
    await auth.api.signOut({ headers: await headers() });
  } catch (error) {
    // No session to revoke is not a failure for the person signing out.
    logger.warn("Better Auth: sign-out reported an error", error);
  }
  if (opts.redirect !== false) redirect(redirectTo);
  return { url: redirectTo };
}

interface CredentialsInput {
  email: string;
  password: string;
  redirect?: boolean;
  redirectTo?: string;
}

const errorMessage = (error: unknown, fallback: string) =>
  error instanceof APIError ? (error.body?.message ?? fallback) : fallback;

/**
 * Email and password flows for the server actions in `src/server/actions/auth.ts`.
 * These replace the Payload-backed `AuthService` methods when Better Auth is active.
 */
export const betterAuthCredentials = {
  async signIn({
    email,
    password,
    redirect: shouldRedirect = false,
    redirectTo,
  }: CredentialsInput) {
    return betterAuthSignIn("credentials", {
      email,
      password,
      redirect: shouldRedirect,
      redirectTo: redirectTo ?? routes.home,
    });
  },

  /** Creates the user row, an account row with the password hash, and a session. */
  async signUp({ email, password }: CredentialsInput) {
    const auth = await getBetterAuth();
    try {
      const result = await auth.api.signUpEmail({
        body: { email, password, name: email },
        headers: await headers(),
      });
      const user = (result as { user?: { id: string; email: string; name?: string | null } }).user;
      if (!user) return { ok: false as const, error: "Sign up failed" };
      return { ok: true as const, user: { id: user.id, email: user.email, name: user.name } };
    } catch (error) {
      if (error instanceof APIError) {
        return { ok: false as const, error: errorMessage(error, "Sign up failed") };
      }
      throw error;
    }
  },

  /** Sends the reset link. Always resolves ok, so an unknown email cannot be probed. */
  async forgotPassword(email: string) {
    const auth = await getBetterAuth();
    await auth.api.requestPasswordReset({
      body: { email, redirectTo: absoluteUrl(routes.auth.resetPassword) },
      headers: await headers(),
    });
    return { ok: true as const };
  },

  async resetPassword(token: string, password: string) {
    const auth = await getBetterAuth();
    try {
      await auth.api.resetPassword({
        body: { token, newPassword: password },
        headers: await headers(),
      });
    } catch (error) {
      throw new Error(errorMessage(error, STATUS_CODES.AUTH_ERROR.message));
    }
    return { ok: true as const };
  },
};

import { env } from "@/env";
import { auth } from "./config";

/**
 * Better Auth Service Layer
 *
 * This service provides utilities for managing Better Auth users,
 * sessions, and integrating with the existing Shipkit architecture.
 */

/**
 * Get the current session from the auth instance
 */
export async function getSession(request: Request) {
  try {
    return await auth.api.getSession({ headers: request.headers });
  } catch (error) {
    console.error("Better Auth: Failed to get session", error);
    return null;
  }
}

/**
 * Check if Better Auth is properly configured
 */
export function isConfigured() {
  return env.NEXT_PUBLIC_FEATURE_BETTER_AUTH_ENABLED;
}

/**
 * Get list of configured OAuth providers for Better Auth
 */
export function getConfiguredProviders(): string[] {
  const providers: string[] = [];

  if (env.NEXT_PUBLIC_FEATURE_AUTH_GOOGLE_ENABLED) providers.push("google");
  if (env.NEXT_PUBLIC_FEATURE_AUTH_GITHUB_ENABLED) providers.push("github");
  if (env.NEXT_PUBLIC_FEATURE_AUTH_DISCORD_ENABLED) providers.push("discord");

  return providers;
}

/**
 * Handle authentication request
 */
export async function handleAuthRequest(request: Request): Promise<Response> {
  try {
    return await auth.handler(request);
  } catch (error) {
    console.error("Better Auth: Failed to handle auth request", error);
    return new Response("Authentication error", { status: 500 });
  }
}

/**
 * Validate session token
 */
export function validateSession(_sessionToken: string) {
  try {
    // TODO: Implement session validation based on Better Auth API
    return null;
  } catch (error) {
    console.error("Better Auth: Failed to validate session", error);
    return null;
  }
}

import { createAuthClient } from "better-auth/react";
import { BASE_URL } from "@/config/base-url";

/**
 * Better Auth client for frontend use
 * @see https://www.better-auth.com/docs/authentication/client
 *
 * This provides hooks and utilities for authentication in React components.
 * Only available when Better Auth is enabled.
 */
export const authClient = createAuthClient({
  baseURL: BASE_URL,
  // Must match `basePath` in src/server/better-auth/config.ts; Auth.js owns /api/auth.
  basePath: "/api/better-auth",
  fetchOptions: {
    onError(e) {
      if (e.error.status === 429) {
        console.warn("Better Auth: Rate limit exceeded");
      }
    },
  },
});

// Export commonly used hooks and methods
export const { useSession, signIn, signUp, signOut, getSession } = authClient;

/**
 * Utility function to check if user is authenticated
 */
export const useIsAuthenticated = () => {
  const { data: session, isPending } = useSession();
  return {
    isAuthenticated: !!session?.user && !isPending,
    isLoading: isPending,
    user: session?.user,
    session,
  };
};

/**
 * Better Auth provider sign-in utilities
 */
export const socialSignIn = {
  google: () => signIn.social({ provider: "google" }),
  github: () => signIn.social({ provider: "github" }),
  discord: () => signIn.social({ provider: "discord" }),
};

/**
 * Email/password authentication utilities
 */
export const emailAuth = {
  signIn: (email: string, password: string) => signIn.email({ email, password }),

  signUp: (email: string, password: string, name: string) =>
    signUp.email({
      email,
      password,
      name,
    }),

  // Note: forgotPassword and resetPassword require the "email-otp" plugin
  // to be enabled in the Better Auth server config
  // forgotPassword: (email: string) => authClient.forgotPassword({ email }),
  // resetPassword: (token: string, newPassword: string) =>
  // 	authClient.resetPassword({ token, newPassword }),
};

/**
 * Two-factor authentication utilities
 */
// export const twoFactorAuth = {
// 	enable: () => authClient.twoFactor.enable(),
// 	disable: () => authClient.twoFactor.disable(),
// 	verify: (code: string) => authClient.twoFactor.verify({ code }),
// };

export type BetterAuthSession = Awaited<ReturnType<typeof getSession>>;
export type BetterAuthUser = BetterAuthSession["user"];

import { env } from "@/env";

/**
 * Better Auth API route handler
 * @see https://www.better-auth.com/docs/installation/nextjs
 *
 * This handles all Better Auth endpoints:
 * - /api/better-auth/sign-in
 * - /api/better-auth/sign-up
 * - /api/better-auth/sign-out
 * - /api/better-auth/session
 * - /api/better-auth/callback/*
 * etc.
 *
 * Only active when Better Auth is properly configured with a database connection.
 */

// Feature gate: Only initialize Better Auth if properly configured
const isBetterAuthConfigured = env.NEXT_PUBLIC_FEATURE_BETTER_AUTH_ENABLED;

export async function GET(request: Request) {
  if (!isBetterAuthConfigured) {
    return new Response("Better Auth is not configured", { status: 404 });
  }

  const { auth } = await import("@/server/better-auth/config");
  return auth.handler(request);
}

export async function POST(request: Request) {
  if (!isBetterAuthConfigured) {
    return new Response("Better Auth is not configured", { status: 404 });
  }

  const { auth } = await import("@/server/better-auth/config");
  return auth.handler(request);
}

"use client";

import { DiscordLogoIcon, GitHubLogoIcon } from "@radix-ui/react-icons";
import { cva } from "class-variance-authority";
import { useState } from "react";
import { toast } from "sonner";
import { Icons } from "@/components/assets/icons";
import {
  useBetterAuthEnabled,
  useBetterAuthProviders,
} from "@/components/providers/better-auth-provider";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { socialSignIn } from "@/lib/better-auth/client";
import { cn } from "@/lib/utils";

const oauthButtonVariants = cva("flex items-center justify-center gap-sm", {
  variants: {
    variant: {
      default: "w-full",
      icons: "w-auto p-2",
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

interface BetterAuthOAuthButtonsProps {
  variant?: "default" | "icons";
  className?: string;
}

interface ProviderConfig {
  id: string;
  name: string;
  icon: React.ReactNode;
}

const providerConfigs: Record<string, ProviderConfig> = {
  google: {
    id: "google",
    name: "Google",
    icon: <Icons.google className="h-4 w-4" />,
  },
  github: {
    id: "github",
    name: "GitHub",
    icon: <GitHubLogoIcon className="h-4 w-4" />,
  },
  discord: {
    id: "discord",
    name: "Discord",
    icon: <DiscordLogoIcon className="h-4 w-4" />,
  },
};

/**
 * Better Auth OAuth Buttons Component
 *
 * This component renders OAuth sign-in buttons for Better Auth providers.
 * It only renders when Better Auth is enabled and configured providers are available.
 */
export function BetterAuthOAuthButtons({
  variant = "default",
  className,
}: BetterAuthOAuthButtonsProps) {
  const isBetterAuthEnabled = useBetterAuthEnabled();
  const availableProviders = useBetterAuthProviders();
  const [loadingProvider, setLoadingProvider] = useState<string | null>(null);

  // Don't render if Better Auth is not enabled or no providers available
  if (!isBetterAuthEnabled || availableProviders.length === 0) {
    return null;
  }

  const handleSignIn = async (providerId: string) => {
    try {
      setLoadingProvider(providerId);

      // Use Better Auth social sign-in
      switch (providerId) {
        case "google":
          await socialSignIn.google();
          break;
        case "github":
          await socialSignIn.github();
          break;
        case "discord":
          await socialSignIn.discord();
          break;
        default:
          throw new Error(`Unsupported provider: ${providerId}`);
      }
    } catch (error) {
      console.error("Better Auth: Sign-in failed", error);
      toast.error(`Failed to sign in with ${providerConfigs[providerId]?.name ?? providerId}`);
    } finally {
      setLoadingProvider(null);
    }
  };

  return (
    <div
      className={cn(
        "flex w-full gap-xs",
        variant === "icons" ? "flex-row justify-center" : "flex-col items-stretch",
        className
      )}
    >
      {availableProviders.map((providerId) => {
        const config = providerConfigs[providerId];
        if (!config) return null;

        const isLoading = loadingProvider === providerId;

        const button = (
          <Button
            variant="outline"
            type="button"
            onClick={() => handleSignIn(providerId)}
            disabled={isLoading}
            className={oauthButtonVariants({ variant })}
          >
            {variant === "default" && (
              <span>{isLoading ? "Signing in..." : `Sign in with ${config.name}`}</span>
            )}
            {config.icon}
          </Button>
        );

        return (
          <div key={providerId}>
            {variant === "icons" ? (
              <Tooltip>
                <TooltipTrigger asChild>{button}</TooltipTrigger>
                <TooltipContent>
                  <p>Sign in with {config.name}</p>
                </TooltipContent>
              </Tooltip>
            ) : (
              button
            )}
          </div>
        );
      })}
    </div>
  );
}

"use client";

import type { ReactNode } from "react";
import { env } from "@/env";

interface BetterAuthProviderProps {
  children: ReactNode;
}

/**
 * Better Auth Provider Component
 *
 * This component provides Better Auth context to the application
 * when Better Auth is enabled. It provides utilities and hooks
 * for Better Auth throughout the app.
 *
 * Only renders when Better Auth is enabled via environment variables.
 */
export function BetterAuthProvider({ children }: BetterAuthProviderProps) {
  // For now, just render children - Better Auth client is available globally
  return <>{children}</>;
}

/**
 * Hook to check if Better Auth is enabled and available
 */
export function useBetterAuthEnabled() {
  return env.NEXT_PUBLIC_FEATURE_BETTER_AUTH_ENABLED;
}

/**
 * Hook to get Better Auth providers that are enabled
 */
export function useBetterAuthProviders() {
  const isBetterAuthEnabled = useBetterAuthEnabled();

  if (!isBetterAuthEnabled) {
    return [];
  }

  const providers = [];

  if (env.NEXT_PUBLIC_FEATURE_AUTH_GOOGLE_ENABLED) {
    providers.push("google");
  }

  if (env.NEXT_PUBLIC_FEATURE_AUTH_GITHUB_ENABLED) {
    providers.push("github");
  }

  if (env.NEXT_PUBLIC_FEATURE_AUTH_DISCORD_ENABLED) {
    providers.push("discord");
  }

  return providers;
}

import { env } from "@/env";

/**
 * Authentication Strategy Types
 */
export type AuthStrategy = "clerk" | "stack" | "authjs" | "better-auth" | "guest";

/**
 * The explicit `AUTH_STRATEGY` choice, if any.
 *
 * The client bundle only sees the `NEXT_PUBLIC_` mirror (features-config.ts
 * copies it at build time); the server can read either, and falls back to the
 * raw variable in scripts and tests where next.config never ran.
 */
function configuredStrategy(): "better-auth" | "authjs" | undefined {
  const isServer = typeof window === "undefined";
  return env.NEXT_PUBLIC_AUTH_STRATEGY ?? (isServer ? env.AUTH_STRATEGY : undefined);
}

/**
 * Whether any Auth.js provider is switched on.
 *
 * This has to be `.some`, not a `??` chain. These flags are optional booleans,
 * so an explicit `NEXT_PUBLIC_FEATURE_AUTH_RESEND_ENABLED=false` is non-nullish
 * and a `??` chain stops right there, reporting guest mode even when GitHub or
 * Google is switched on.
 */
function hasAuthJsProvider(): boolean {
  return [
    env.NEXT_PUBLIC_FEATURE_AUTH_RESEND_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_CREDENTIALS_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_GITHUB_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_GOOGLE_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_DISCORD_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_GITLAB_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_BITBUCKET_ENABLED,
    env.NEXT_PUBLIC_FEATURE_AUTH_TWITTER_ENABLED,
  ].some(Boolean);
}

/**
 * Something only an Auth.js deployment would set: a session strategy override,
 * or the Payload-backed credentials provider.
 */
function hasAuthJsSignal(): boolean {
  const isServer = typeof window === "undefined";
  const sessionStrategy = isServer ? env.NEXTAUTH_SESSION_STRATEGY : undefined;
  return Boolean(sessionStrategy) || env.NEXT_PUBLIC_FEATURE_AUTH_CREDENTIALS_ENABLED === true;
}

/**
 * Determines which authentication strategy to use.
 *
 * Priority: Clerk > Stack Auth > explicit AUTH_STRATEGY > Better Auth > Auth.js > Guest
 *
 * - `AUTH_STRATEGY=better-auth` picks Better Auth when it is configured
 *   (DATABASE_URL plus BETTER_AUTH_SECRET or APP_SECRET).
 * - `AUTH_STRATEGY=authjs` keeps the Auth.js provider detection.
 * - Unset: Better Auth when it is configured and nothing Auth.js-specific is,
 *   otherwise the Auth.js detection. That makes Better Auth the default for a
 *   new project while an existing Auth.js deployment keeps working untouched.
 */
export function getAuthStrategy(): AuthStrategy {
  // // Check if Clerk is configured
  // if (env.NEXT_PUBLIC_FEATURE_AUTH_CLERK_ENABLED === true) {
  // 	return "clerk";
  // }

  // // Check if Stack Auth is configured
  // if (env.NEXT_PUBLIC_FEATURE_AUTH_STACK_ENABLED === true) {
  // 	return "stack";
  // }

  const configured = configuredStrategy();
  const betterAuthReady = env.NEXT_PUBLIC_FEATURE_BETTER_AUTH_ENABLED === true;

  if (configured === "better-auth" && betterAuthReady) {
    return "better-auth";
  }

  if (configured === undefined && betterAuthReady && !hasAuthJsSignal()) {
    return "better-auth";
  }

  if (hasAuthJsProvider()) {
    return "authjs";
  }

  // Fall back to guest mode
  return "guest";
}

/**
 * Check if authentication is available
 */
export function isAuthenticationAvailable(): boolean {
  return getAuthStrategy() !== "guest";
}

/**
 * Check if Clerk is the active auth strategy
 */
export function isClerkActive(): boolean {
  return getAuthStrategy() === "clerk";
}

/**
 * Check if Auth.js is the active auth strategy
 */
export function isAuthJSActive(): boolean {
  return getAuthStrategy() === "authjs";
}

/**
 * Check if Better Auth is the active auth strategy
 */
export function isBetterAuthActive(): boolean {
  return getAuthStrategy() === "better-auth";
}

/**
 * Check if guest mode is active
 */
export function isGuestModeActive(): boolean {
  return getAuthStrategy() === "guest";
}

import type { Session } from "next-auth";
import { type User, UserRole } from "@/types/user";

/**
 * Better Auth session -> Auth.js `Session`.
 *
 * Pure and dependency-free so both the server facade (`@/server/better-auth/facade`)
 * and the client hook (`@/lib/auth/use-session`) produce the same shape, which is
 * what every component and service in the app reads.
 */

/** The subset of a Better Auth session (server `getSession` or client `useSession`) that is read. */
export interface BetterAuthSessionResult {
  session: { expiresAt: Date | string };
  user: {
    id: string;
    email: string;
    name?: string | null;
    image?: string | null;
    emailVerified?: boolean | null;
    emailVerifiedAt?: Date | string | null;
    role?: string | null;
    createdAt?: Date | string;
    updatedAt?: Date | string;
  };
}

const toDate = (value: Date | string | null | undefined): Date | null => {
  if (value === null || value === undefined) return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};

const toRole = (value: string | null | undefined): UserRole =>
  value === UserRole.admin ? UserRole.admin : UserRole.user;

/**
 * `emailVerified` prefers the Auth.js timestamp (read through the
 * `emailVerifiedAt` additional field) and falls back to the boolean flag.
 */
export function mapBetterAuthSession(result: BetterAuthSessionResult | null): Session | null {
  if (!result?.user?.id) return null;
  const { user, session } = result;
  const role = toRole(user.role);
  const emailVerified = toDate(user.emailVerifiedAt) ?? (user.emailVerified ? new Date() : null);
  const expires = toDate(session.expiresAt) ?? new Date(0);

  const mapped: User = {
    id: user.id,
    email: user.email,
    name: user.name ?? null,
    image: user.image ?? null,
    emailVerified,
    role,
    isAdmin: role === UserRole.admin,
    createdAt: toDate(user.createdAt) ?? undefined,
    updatedAt: toDate(user.updatedAt) ?? undefined,
  };

  return { user: mapped, expires: expires.toISOString() };
}

"use client";

import type { Session } from "next-auth";
import {
  signIn as nextAuthSignIn,
  signOut as nextAuthSignOut,
  useSession as useNextAuthSession,
} from "next-auth/react";
import { useCallback, useEffect, useMemo } from "react";
import { routes } from "@/config/routes";
import { isBetterAuthActive } from "@/lib/auth/auth-strategy";
import { type BetterAuthSessionResult, mapBetterAuthSession } from "@/lib/auth/session-mapping";
import { authClient } from "@/lib/better-auth/client";

/**
 * Client-side session with the `next-auth/react` API, whichever strategy is on.
 *
 * Components import `useSession`, `signIn` and `signOut` from here instead of
 * `next-auth/react`. Under Auth.js they are the `next-auth/react` originals.
 * Under Better Auth, `useSession` reads `authClient.useSession()` and maps it
 * to `{ data: { user, expires } | null, status, update }`, and `signIn` /
 * `signOut` call the Better Auth client. The strategy is fixed for the life of
 * the bundle, so the choice is made once at module load.
 *
 * `SessionProvider` still comes from `next-auth/react`; it wraps the tree and
 * is harmless when Better Auth owns the session.
 */

type NextAuthUseSession = typeof useNextAuthSession;
type NextAuthSignIn = typeof nextAuthSignIn;
type NextAuthSignOut = typeof nextAuthSignOut;

type SessionStatus = "loading" | "authenticated" | "unauthenticated";

/** `next-auth/react` declares this but does not export it. */
interface UseSessionOptions<R extends boolean> {
  required: R;
  onUnauthenticated?: () => void;
}

interface SignInOptionsLike {
  redirectTo?: string;
  callbackUrl?: string;
  redirect?: boolean;
  email?: string;
  password?: string;
  [key: string]: unknown;
}

interface SignOutOptionsLike {
  redirectTo?: string;
  callbackUrl?: string;
  redirect?: boolean;
}

/** Providers Better Auth's client can start itself; anything else falls back to Auth.js. */
const CREDENTIALS_PROVIDER = "credentials";
const AUTHJS_ONLY_PROVIDERS = new Set(["guest", "resend", "email", "nodemailer"]);

const currentPage = () => (typeof window === "undefined" ? routes.home : window.location.href);

const navigate = (url: string) => {
  if (typeof window !== "undefined") window.location.href = url;
};

function useBetterAuthSession<R extends boolean>(options?: UseSessionOptions<R>) {
  const { data, isPending, refetch } = authClient.useSession();
  const session = useMemo(
    () => mapBetterAuthSession(data as unknown as BetterAuthSessionResult | null),
    [data]
  );
  const status: SessionStatus = isPending
    ? "loading"
    : session
      ? "authenticated"
      : "unauthenticated";

  const update = useCallback(async (): Promise<Session | null> => {
    await refetch();
    const fresh = await authClient.getSession();
    return mapBetterAuthSession(fresh.data);
  }, [refetch]);

  const required = options?.required === true;
  const onUnauthenticated = options?.onUnauthenticated;
  useEffect(() => {
    if (!required || status !== "unauthenticated") return;
    if (onUnauthenticated) onUnauthenticated();
    else navigate(routes.auth.signIn);
  }, [required, status, onUnauthenticated]);

  return { data: session, status, update };
}

export const useSession = (
  isBetterAuthActive() ? useBetterAuthSession : useNextAuthSession
) as NextAuthUseSession;

async function betterAuthSignIn(provider: string | undefined, options?: SignInOptionsLike) {
  const callbackURL = options?.redirectTo ?? options?.callbackUrl ?? currentPage();
  const shouldRedirect = options?.redirect !== false;

  if (provider === CREDENTIALS_PROVIDER) {
    const { data, error } = await authClient.signIn.email({
      email: typeof options?.email === "string" ? options.email : "",
      password: typeof options?.password === "string" ? options.password : "",
      callbackURL,
    });
    if (!error && shouldRedirect) navigate(callbackURL);
    return {
      ok: !error,
      error: error?.message ?? error?.code,
      code: error?.code,
      status: error?.status ?? 200,
      url: data ? callbackURL : null,
    };
  }

  const { data, error } = await authClient.signIn.social({
    provider: provider ?? "github",
    callbackURL,
    disableRedirect: !shouldRedirect,
  });
  return {
    ok: !error,
    error: error?.message ?? error?.code,
    code: error?.code,
    status: error?.status ?? 200,
    url: data?.url ?? null,
  };
}

/**
 * `signIn(provider, options)` from `next-auth/react`, or the Better Auth
 * client when it is active. Social providers start the OAuth flow, and
 * `"credentials"` signs in with email and password. `redirect: false` returns
 * the `{ ok, error, url }` response instead of navigating. Auth.js-only
 * providers (`guest`, `resend`) always go through Auth.js.
 */
export const signIn = (async (
  provider?: string,
  options?: SignInOptionsLike | FormData,
  authorizationParams?: unknown
) => {
  const opts =
    options instanceof FormData ? (Object.fromEntries(options) as SignInOptionsLike) : options;
  if (!isBetterAuthActive() || (provider && AUTHJS_ONLY_PROVIDERS.has(provider))) {
    return (nextAuthSignIn as (...args: unknown[]) => Promise<unknown>)(
      provider,
      options,
      authorizationParams
    );
  }
  return betterAuthSignIn(provider, opts);
}) as NextAuthSignIn;

/**
 * `signOut(options)` from `next-auth/react`, or the Better Auth client when it
 * is active: revokes the session, then navigates to `callbackUrl` /
 * `redirectTo` (default home) unless `redirect: false`.
 */
export const signOut = (async (options?: SignOutOptionsLike) => {
  if (!isBetterAuthActive()) {
    return (nextAuthSignOut as (...args: unknown[]) => Promise<unknown>)(options);
  }
  const url = options?.redirectTo ?? options?.callbackUrl ?? routes.home;
  await authClient.signOut();
  if (options?.redirect !== false) navigate(url);
  return { url };
}) as NextAuthSignOut;
